// Compact probe: one line per case.  node p.mjs --inline '["a","b"]'
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test2_executable';
const args = process.argv.slice(2);
let entries;
if (args[0] === '--inline') entries = JSON.parse(args[1]);
else entries = JSON.parse(readFileSync(args[0], 'utf8'));
for (const entry of entries) {
  const argv = Array.isArray(entry) ? entry.map(String) : ['--a', String(entry)];
  const r = spawnSync(EXE, argv, { encoding: 'utf8', maxBuffer: 1 << 28 });
  const out = (r.stdout ?? '').replace(/\n$/, '');
  console.log(JSON.stringify(Array.isArray(entry) ? entry : String(entry)) + '  ==>  ' + (r.status === 0 ? out : 'CODE=' + r.status + ' ' + JSON.stringify(r.stderr)));
}

// Level measurement: for each prefix, find minimal n in 0..N such that
// prefix + ' ' + ')'*n + '; SELECT 1;'  splits into >=2 statements.
// Reports n (the effective `level` at that point) or '>N'.
import { spawnSync } from 'node:child_process';
const EXE = '/workspace/dataset/test2_executable';
const prefixes = JSON.parse(process.argv[2]);
const MAX = process.argv[3] ? Number(process.argv[3]) : 6;
const closer = process.argv[4] ?? ')';
function run(s) {
  const r = spawnSync(EXE, ['--a', s], { encoding: 'utf8', maxBuffer: 1 << 28 });
  return (r.stdout ?? '').replace(/\n$/, '');
}
for (const p of prefixes) {
  let found = null; let outs = [];
  for (let n = 0; n <= MAX; n++) {
    const s = p + ' ' + closer.repeat(n) + '; SELECT 1;';
    const out = run(s);
    // split happened if output has ", '" separator at top level (2+ items)
    const items = out.startsWith('[') && out.endsWith(']');
    const two = out.includes("', 'SELECT 1;'") || out.includes('", \'SELECT 1;\'') || out.includes("\", 'SELECT 1;'");
    outs.push(n + ':' + (two ? 'SPLIT' : 'one'));
    if (two && found === null) found = n;
  }
  console.log(JSON.stringify(p) + '   level=' + (found === null ? '>' + MAX : found) + '   [' + outs.join(' ') + ']');
}

