// For each word W, run `BEGIN W; SELECT 2;` and report whether it split
// (split => `BEGIN W` did NOT act as a bare BEGIN keyword).
import { spawnSync } from 'node:child_process';
const EXE = '/workspace/dataset/test2_executable';
const words = JSON.parse(process.argv[2]);
const tmpl = process.argv[3] ?? 'BEGIN @; SELECT 2;';
const swallowed = [], bare = [];
for (const w of words) {
  const s = tmpl.split('@').join(w);
  const r = spawnSync(EXE, ['--a', s], { encoding: 'utf8' });
  const out = (r.stdout ?? '').replace(/\n$/, '');
  const split = out.includes("', 'SELECT 2;'") || out.includes("', 'SELECT 1;'");
  (split ? swallowed : bare).push(w);
}
console.log('SPLIT (phrase absorbed / no bare keyword): ' + JSON.stringify(swallowed));
console.log('NO SPLIT (bare keyword acted)            : ' + JSON.stringify(bare));

